173	    fn get_aqua_matches(
174	        &self,
175	        name: &str,
176	        fuzzy_matcher: &mut FuzzyMatcher,
177	        fuzzy_pattern: &FuzzyPattern,
178	    ) -> Vec<(u32, String, String)> {
179	        if name.is_empty() {
180	            return vec![];
181	        }
182	
183	        crate::aqua::aqua_registry_wrapper::aqua_search_entries()
184	            .filter_map(|entry| {
185	                let tool_name = entry.name();
186	                let score = if entry.backend_matches(name) {
187	                    Some(0)
188	                } else {
189	                    match self.match_type {
190	                        MatchType::Equal => {
191	                            if tool_name == name || entry.id == name {
192	                                Some(0)
193	                            } else {
194	                                None
195	                            }
196	                        }
197	                        MatchType::Contains => {
198	                            if tool_name.contains(name) || entry.id.contains(name) {
199	                                Some(0)
200	                            } else {
201	                                None
202	                            }
203	                        }
204	                        MatchType::Fuzzy => {
205	                            fuzzy_matcher.score_pattern(&tool_name.to_lowercase(), fuzzy_pattern)
206	                        }
207	                    }
208	                }?;
209	
210	                let search_backend = entry.backend();
211	                let description = get_aqua_description(entry.id, &search_backend);
212	
213	                Some((score, search_backend, description))
214	            })
215	            // Distinct aqua packages can translate to the same backend
216	            // (e.g. crates.io/eza and eza-community/eza both to cargo:eza)
217	            .unique_by(|(_score, search_backend, _description)| search_backend.clone())
