664	fn merge_plugin_tools(tools: &mut InstallStateTools, plugins: &InstallStatePlugins) {
665	    for (short, pt) in plugins {
666	        let full = match pt {
667	            PluginType::Asdf => format!("asdf:{short}"),
668	            PluginType::Vfox => format!("vfox:{short}"),
669	            PluginType::VfoxBackend => short.clone(),
670	            PluginType::Package => continue,
671	        };
672	        let tool = tools
673	            .entry(short.clone())
674	            .or_insert_with(|| InstallStateTool {
675	                short: short.clone(),
676	                full: Some(full.clone()),
677	                versions: Default::default(),
678	                explicit_backend: true,
679	                opts: BTreeMap::new(),
680	                installs_path: None,
681	            });
682	        // Installed metadata describes the versions already on disk. Plugin
683	        // discovery should only supply an identity when no metadata exists.
684	        tool.full.get_or_insert(full);
685	    }
686	}
