177	        fuzzy_pattern: &FuzzyPattern,
178	    ) -> Vec<(u32, String, String)> {
179	        if name.is_empty() {
180	            return vec![];
181	        }
182	
183	        crate::aqua::aqua_registry_wrapper::aqua_search_entries()
184	            .filter_map(|entry| {
