186	                let score = if entry.backend_matches(name) {
187	                    Some(0)
188	                } else {
189	                    match self.match_type {
190	                        MatchType::Equal => {
191	                            if tool_name == name || entry.id == name {
192	                                Some(0)
193	                            } else {
194	                                None
195	                            }
196	                        }
197	                        MatchType::Contains => {
198	                            if tool_name.contains(name) || entry.id.contains(name) {
199	                                Some(0)
200	                            } else {
201	                                None
202	                            }
203	                        }
204	                        MatchType::Fuzzy => {
205	                            fuzzy_matcher.score_pattern(&tool_name.to_lowercase(), fuzzy_pattern)
206	                        }
207	                    }
208	                }?;
