127	    fn get_matches(&self) -> Vec<(String, String)> {
128	        let name = self.name.as_deref().unwrap_or("");
129	        let mut fuzzy_matcher = FuzzyMatcher::default();
130	        let fuzzy_pattern = FuzzyPattern::new(&name.to_lowercase());
131	        let mut matches = self
132	            .get_tools()
133	            .iter()
134	            .filter_map(|(short, rt)| {
135	                if name.is_empty() {
136	                    Some((0, short, rt))
137	                } else {
138	                    match self.match_type {
139	                        MatchType::Equal => {
140	                            if *short == name {
141	                                Some((0, short, rt))
142	                            } else {
143	                                None
144	                            }
145	                        }
146	                        MatchType::Contains => {
147	                            if short.contains(name) {
148	                                Some((0, short, rt))
149	                            } else {
150	                                None
151	                            }
152	                        }
153	                        MatchType::Fuzzy => fuzzy_matcher
154	                            .score_pattern(&short.to_lowercase(), &fuzzy_pattern)
155	                            .map(|score| (score, short, rt)),
156	                    }
157	                }
158	            })
159	            .map(|(score, short, rt)| (score, short.to_string(), get_description(rt)))
160	            .collect_vec();
161	
162	        if matches.is_empty() {
163	            matches.extend(self.get_aqua_matches(name, &mut fuzzy_matcher, &fuzzy_pattern));
164	        }
165	
166	        matches
167	            .into_iter()
168	            .sorted_by_key(|(score, _short, _description)| std::cmp::Reverse(*score))
169	            .map(|(_score, short, description)| (short, description))
170	            .collect()
171	    }
