        Ok(match context.as_deref() {
            Some(context) => self.get_remote_version_cache_with_context(Some(context)),
            None => self.get_remote_version_cache(),
        })
    }

    fn get_remote_version_cache(&self) -> Arc<TokioMutex<VersionCacheManager>> {
        self.get_remote_version_cache_with_context(None)
    }

    fn get_remote_version_cache_with_context(
        &self,
        context: Option<&str>,
    ) -> Arc<TokioMutex<VersionCacheManager>> {
        // use a mutex to prevent deadlocks that occurs due to reentrant cache access
        static REMOTE_VERSION_CACHE: Lazy<
            Mutex<HashMap<String, Arc<TokioMutex<VersionCacheManager>>>>,
        > = Lazy::new(Default::default);

        let map_key = match context {
            Some(context) => format!("{}\0{context}", self.ba().full()),
            None => self.ba().full(),
        };
        REMOTE_VERSION_CACHE
            .lock()
            .unwrap()
            .entry(map_key)
            .or_insert_with(|| {
                let mut cm = CacheManagerBuilder::new(
                    self.ba().cache_path.join("remote_versions.msgpack.z"),
                )
                .with_cache_key(self.ba().full())
                .with_fresh_duration(Settings::get().fetch_remote_versions_cache());
                if let Some(context) = context {
                    cm = cm.with_cache_key(context.to_string());
                }
                if let Some(plugin_path) = self.plugin().map(|p| p.path()) {
                    cm = cm
                        .with_fresh_file(plugin_path.clone())
                        .with_fresh_file(plugin_path.join("bin/list-all"))
                }

                TokioMutex::new(cm.build()).into()
            })
            .clone()
    }

    fn verify_checksum(
        &self,
        ctx: &InstallContext,
        tv: &mut ToolVersion,
        file: &Path,
    ) -> Result<()> {
        let settings = Settings::get();
        let filename = file.file_name().unwrap().to_string_lossy().to_string();
        let lockfile_enabled = settings.lockfile_enabled();

        // Get the platform key for this tool and platform
        let platform_key = self.get_platform_key();

        // Get or create asset info for this platform
        let locked = tv
            .lock_platforms
            .entry(platform_key.clone())
    // An identity or URL in inline options may contain '@'. Only a separator
    // after the closing bracket starts a version; scoped package names still
    // follow the ordinary rules below.
    if let Some((name, _, suffix)) = super::backend_arg::split_bracketed_opts_with_suffix(s)
        && parse_input(name) == (name, None)
    {
        if suffix.is_empty() {
            return (s, None);
        }
        if let Some(version) = suffix.strip_prefix('@') {
            return (
                &s[..s.len() - suffix.len()],
                (!version.is_empty()).then_some(version),
            );
        }
    }

    let Some((left, right)) = s.split_once('@') else {
        return (s, None);
    };

    if left.is_empty() {
        // Scoped package name starting with '@' (e.g., "@anthropic-ai/claude-code")
        // The first '@' is part of the name, not a version separator
        // Look for a second '@' to separate name from version
        return right
            .split_once('@')
            .map(|(name, version)| {
                (
                    &s[..name.len() + 1],
                    if version.is_empty() {
                        None
                    } else {
                        Some(version)
                    },
                )
            })
            .unwrap_or((s, None));
    }

    if left.ends_with(':') {
        // Backend format: try to find version in the remaining part
        return right
            .split_once('@')
            .map(|(tool, version)| {
                (
                    &s[..left.len() + tool.len() + 1],
                    if version.is_empty() {
                        None
                    } else {
                        Some(version)
                    },
                )
            })
            .unwrap_or((s, None));
    }

    // Simple "tool@version" format
    (left, if right.is_empty() { None } else { Some(right) })
}

