                root_path: install_dir.to_path_buf(),
                runtime_version: version.to_string(),
                sdk_info: BTreeMap::from([(sdk_info.name.clone(), sdk_info)]),
                options,
            })
            .await?;
        }
        Ok(InstallResult {
            sha256: pre_install.sha256,
            verified_attestation,
            checksum_verified,
        })
    }

