        }

        matches
            .into_iter()
            .sorted_by_key(|(score, _short, _description)| std::cmp::Reverse(*score))
            .map(|(_score, short, description)| (short, description))
            .collect()
    }

    fn get_aqua_matches(
        &self,
        name: &str,
        fuzzy_matcher: &mut FuzzyMatcher,
        fuzzy_pattern: &FuzzyPattern,
    ) -> Vec<(u32, String, String)> {
        if name.is_empty() {
            return vec![];
        }

        crate::aqua::aqua_registry_wrapper::aqua_search_entries()
            .filter_map(|entry| {
                let tool_name = entry.name();
                let score = if entry.backend_matches(name) {
                    Some(0)
                } else {
                    match self.match_type {
                        MatchType::Equal => {
                            if tool_name == name || entry.id == name {
                                Some(0)
                            } else {
                                None
                            }
                        }
                        MatchType::Contains => {
                            if tool_name.contains(name) || entry.id.contains(name) {
                                Some(0)
                            } else {
                                None
                            }
                        }
                        MatchType::Fuzzy => {
                            fuzzy_matcher.score_pattern(&tool_name.to_lowercase(), fuzzy_pattern)
                        }
                    }
                }?;

                let search_backend = entry.backend();
                let description = get_aqua_description(entry.id, &search_backend);

                Some((score, search_backend, description))
            })
            // Distinct aqua packages can translate to the same backend
            // (e.g. crates.io/eza and eza-community/eza both to cargo:eza)
            .unique_by(|(_score, search_backend, _description)| search_backend.clone())
            .collect()
    }

    fn print_completions(&self, tools: &[ToolCatalogEntry], descriptions: bool) {
        for tool in tools {
            if descriptions {
                println!(
                    "{}:{}",
                    tool.id.replace(':', "\\:"),
                    tool.selector_description().replace(':', "\\:")
                );
            } else {
                println!("{}", tool.id);
            }
        }
    }
}

fn search_description(tool: &ToolCatalogEntry) -> String {
    match &tool.source {
        ToolCatalogSource::Registry(registry_tool) => get_description(registry_tool),
        ToolCatalogSource::VfoxBackend => {
            tool.description.clone().unwrap_or_else(|| tool.id.clone())
        }
    }
}

fn get_description(tool: &RegistryTool) -> String {
    let description = tool.description.unwrap_or_default();
    let backend = get_backends(tool.backends())
        .iter()
        .filter(|b| !Settings::get().disable_backends.contains(b))
        .map(|b| b.to_string())
        .next()
        .unwrap_or_default();
    if description.is_empty() {
        backend.to_string()
    } else {
        format!("{description}. {backend}")
    }
}

fn get_backends(backends: Vec<&'static str>) -> Vec<String> {
    if backends.is_empty() {
        return vec!["".to_string()];
    }
    backends
        .iter()
        .map(|backend| {
            let prefix = backend.split(':').next().unwrap_or("");
            let slug = backend.split(':').next_back().unwrap_or("");
            let slug = regex!(r"^(.*?)\[.*\]$").replace_all(slug, "$1");
            backend_homepage_url(prefix, &slug)
                .unwrap_or_else(|| format!("https://github.com/{slug}"))
        })
        .collect()
}

fn backend_homepage_url(prefix: &str, slug: &str) -> Option<String> {
    match prefix {
        "core" => Some(format!("https://mise.jdx.dev/lang/{slug}.html")),
        "cargo" => Some(format!("https://crates.io/crates/{slug}")),
        "go" => Some(format!("https://pkg.go.dev/{slug}")),
        "pipx" => Some(format!("https://pypi.org/project/{slug}")),
        "npm" => Some(format!("https://www.npmjs.com/package/{slug}")),
        _ => None,
    }
}

fn get_aqua_description(id: &str, search_backend: &str) -> String {
    let fallback = search_backend.to_string();
    let Ok(pkg) =
        crate::aqua::standard_registry::package(id).unwrap_or_else(|| Ok(Default::default()))
    else {
        return fallback;
    };

    let backend = if !pkg.repo_owner.is_empty() && !pkg.repo_name.is_empty() {
        format!("https://github.com/{}/{}", pkg.repo_owner, pkg.repo_name)
    } else {
        let (backend_type, tool) = search_backend.split_once(':').unwrap_or_default();
        backend_homepage_url(backend_type, tool).unwrap_or(fallback)
    };

    match pkg.description.as_deref().filter(|d| !d.is_empty()) {
        Some(description) => format!("{description}. {backend}"),
        None => backend,
    }
}
use std::path::Path;

use heck::ToKebabCase;
use itertools::Itertools;

use crate::cache::CacheManagerBuilder;
use crate::config::Settings;
use crate::plugins::PluginType;
use crate::plugins::vfox_plugin::VfoxPlugin;
use crate::registry::{REGISTRY, RegistryTool, tool_enabled};
use crate::toolset::install_state;
use crate::{dirs, timeout};

#[derive(Debug, Clone)]
pub(crate) enum ToolCatalogSource {
    Registry(&'static RegistryTool),
    VfoxBackend,
}

#[derive(Debug, Clone)]
pub(crate) struct ToolCatalogEntry {
    pub id: String,
    pub name: String,
    pub description: Option<String>,
    pub source: ToolCatalogSource,
}

impl ToolCatalogEntry {
    pub(crate) fn canonical_id(&self) -> &str {
        match &self.source {
            ToolCatalogSource::Registry(tool) => tool.short,
            ToolCatalogSource::VfoxBackend => &self.id,
        }
    }

    pub(crate) fn selector_description(&self) -> &str {
        match &self.source {
            ToolCatalogSource::Registry(tool) => tool
                .description
                .or_else(|| tool.backends().first().copied())
                .unwrap_or_default(),
            ToolCatalogSource::VfoxBackend => self.description.as_deref().unwrap_or_default(),
        }
    }
}

pub(crate) async fn list() -> Vec<ToolCatalogEntry> {
    let settings = Settings::get();
    let enable_tools = settings.enable_tools();
    let disable_tools = settings.disable_tools();
    let mut entries = REGISTRY
        .iter()
        .filter(|(short, _)| {
            tool_enabled(enable_tools.as_ref(), &disable_tools, &short.to_string())
        })
        .map(|(short, tool)| ToolCatalogEntry {
            id: short.to_string(),
            name: short.to_string(),
            description: tool.description.map(str::to_string),
            source: ToolCatalogSource::Registry(tool),
        })
        .collect_vec();

    let Some(plugins) = install_state::try_list_plugins() else {
        return entries;
    };
    for (plugin_name, plugin_type) in plugins.iter() {
        if *plugin_type != PluginType::VfoxBackend
            || settings.disable_backends.contains(plugin_name)
        {
            continue;
        }
        let plugin_path = dirs::PLUGINS.join(plugin_name.to_kebab_case());
        if !plugin_path.exists() || !plugin_path.join("hooks/backend_list_tools.lua").exists() {
            continue;
        }
        let tools = cached_backend_tools(plugin_name, &plugin_path).await;
        entries.extend(tools.into_iter().filter_map(|tool| {
            let name = tool.name.trim();
            if !valid_tool_name(name) {
                debug!("ignoring invalid tool name from backend plugin {plugin_name}: {name:?}");
                return None;
            }
            let id = format!("{plugin_name}:{name}");
            if !tool_enabled(enable_tools.as_ref(), &disable_tools, &id) {
                return None;
            }
            Some(ToolCatalogEntry {
                id,
                name: name.to_string(),
                description: tool
                    .description
                    .filter(|description| !description.is_empty()),
                source: ToolCatalogSource::VfoxBackend,
            })
        }));
    }

    entries
        .into_iter()
        .unique_by(|entry| entry.id.clone())
        .collect()
}

async fn cached_backend_tools(plugin_name: &str, plugin_path: &Path) -> Vec<vfox::BackendTool> {
    let cache = CacheManagerBuilder::new(
        dirs::CACHE
            .join(plugin_name.to_kebab_case())
            .join("backend_tools.msgpack.z"),
    )
    .with_cache_key(plugin_name.to_string())
    .with_fresh_duration(Settings::get().fetch_remote_versions_cache())
    .with_fresh_file(plugin_path.to_path_buf())
    .with_fresh_file(plugin_path.join("hooks/backend_list_tools.lua"))
    .build();
    let plugin = VfoxPlugin::new(plugin_name.to_string(), plugin_path.to_path_buf());
    match cache
        .get_or_try_init_async(|| async {
            timeout::run_with_timeout_async(
                || async { Ok(plugin.backend_list_tools().await?.unwrap_or_default()) },
                Settings::get().fetch_remote_versions_timeout(),
            )
            .await
        })
        .await
    {
        Ok(tools) => tools.clone(),
        Err(err) => match cache.get_cached() {
            Ok(tools) => {
                debug!(
                    "failed to refresh tool catalog from backend plugin {plugin_name}, using stale cache: {err:#}"
                );
                tools
            }
            Err(_) => {
                debug!("failed to list tools from backend plugin {plugin_name}: {err:#}");
                vec![]
            }
        },
    }
}

fn valid_tool_name(name: &str) -> bool {
    let valid_at = !name.contains('@')
        || name
            .strip_prefix('@')
            .is_some_and(|scoped| !scoped.contains('@'));
    !name.is_empty()
        && valid_at
        && !name.chars().any(char::is_whitespace)
        && !name.contains([':', '[', ']'])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_tool_name() {
        assert!(valid_tool_name("prettier"));
        assert!(valid_tool_name("@scope/tool"));
        assert!(!valid_tool_name(""));
        assert!(!valid_tool_name("other:tool"));
        assert!(!valid_tool_name("two tools"));
        assert!(!valid_tool_name("tool[option=true]"));
        assert!(!valid_tool_name("tool@version"));
        assert!(!valid_tool_name("@scope/tool@version"));
    }
}
